"""Freeze the owner's sample as a test fixture (D-044).

Run once, from the repo root, inside the venv:

    python tests/fixtures/make_sample.py data/backups/collection-20261118-235202.json

Writes tests/fixtures/sample_2026-11-18/:
    collection.json  the backup export, unchanged (what you own and where)
    cards.json       every printing of every card in it, from the real catalog
    SAMPLE.md        the same thing as a page to check the screen against by eye

The real database is opened read-only. Kept in the repo so the fixture can be
regenerated the same way for a later sample.
"""

from __future__ import annotations

import json
import shutil
import sqlite3
import sys
from collections import defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = Path(__file__).resolve().parent / "sample_2026-11-18"
CARD_COLUMNS = ["card_image_id", "base_card_id", "printing_variant", "printing_kind", "name",
                "category", "cost", "color", "set_code", "game_set", "rarity", "image_url"]


def main(export_path: str) -> None:
    export = json.loads(Path(export_path).read_text(encoding="utf-8"))
    holders = [*export["locations"], *export["decks"]]
    ids = sorted({c["card"] for h in holders for c in h["copies"]}
                 | {r["card"] for d in export["decks"] for r in d["recipe"]})

    db = sqlite3.connect(f"file:{ROOT / 'data' / 'optcg.db'}?mode=ro", uri=True)
    marks = ",".join("?" * len(ids))
    rows = db.execute(
        f"SELECT {', '.join(CARD_COLUMNS)} FROM cards WHERE base_card_id IN ({marks}) "
        "ORDER BY card_image_id", ids).fetchall()
    db.close()
    cards = [dict(zip(CARD_COLUMNS, r)) for r in rows]

    OUT.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(export_path, OUT / "collection.json")
    (OUT / "cards.json").write_text(json.dumps(cards, indent=1, ensure_ascii=False) + "\n",
                                    encoding="utf-8")
    (OUT / "SAMPLE.md").write_text(sample_page(export, cards), encoding="utf-8")
    print(f"{len(ids)} cards, {len(cards)} printings -> {OUT}")


def sample_page(export: dict, cards: list[dict]) -> str:
    names = {c["base_card_id"]: c["name"] for c in cards if c["card_image_id"] == c["base_card_id"]}
    arts = defaultdict(int)
    for c in cards:
        arts[c["base_card_id"]] += 1

    holders = [(loc["kind"], loc["name"], loc["copies"]) for loc in export["locations"]]
    holders += [("deck", d["name"], d["copies"]) for d in export["decks"] if d["physical"]]
    total = sum(c["quantity"] for _, _, copies in holders for c in copies)
    distinct = {c["card"] for _, _, copies in holders for c in copies}

    lines = [
        "# The 2026-11-18 sample",
        "",
        "What the browser page must show, place by place (D-044). Generated by",
        "`make_sample.py` from the backup export; don't edit by hand.",
        "",
        f"**{total} copies of {len(distinct)} cards in {len(holders)} places.** "
        "No art recorded yet: every copy is *unsorted*.",
        "",
        "| Place | Type | Cards | Copies |",
        "|---|---|---|---|",
    ]
    for kind, name, copies in holders:
        lines.append(f"| {name} | {kind} | {len({c['card'] for c in copies})} | "
                     f"{sum(c['quantity'] for c in copies)} |")
    for kind, name, copies in holders:
        lines += ["", f"## {name} ({kind})", "", "| Card | Name | Copies | Art | Arts that exist |",
                  "|---|---|---|---|---|"]
        for c in sorted(copies, key=lambda c: (c["card"], c["art"] or "")):
            lines.append(f"| {c['card']} | {names.get(c['card'], c.get('name') or '?')} | "
                         f"{c['quantity']} | {c['art'] or 'unsorted'} | {arts[c['card']]} |")
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    main(sys.argv[1])
